{const ob=SYS.openBox,br=SYS.boxRod;SYS.openBox=function(){const r=ob.apply(this,arguments);try{if(r&&r.tier!=null)XBAL.box(r.tier);}catch(e){}return r;};
 SYS.boxRod=function(D,tier,rnd){let k=br.apply(this,arguments);try{const c=XBAL.cfg(),L=myLv();if(c.rc&&L<=(c.rmax|0)&&rodNeed(k)>L&&Math.random()<(+c.rp||0)/100){const ok=D.RODS.filter(r=>!r.tx&&r.k!=='heaven'&&r.k!=='fire'&&rodNeed(r.k)<=L).sort((a,b)=>rodNeed(b.k)-rodNeed(a.k));if(ok.length)k=ok[0].k;}}catch(e){}return k;};}
function rodNeed(k){const r=D.RODS.find(x=>x.k===k);return (r&&r.reqLv!=null?r.reqLv:LV.rods[k])||1;}
function lvRodOK(k){return myLv()>=rodNeed(k)||lvK().rods.includes(k);}
// 자동낚시 이용 시간 — 닉네임 기준 localStorage (특별 칭호 nk_sptitle과 같은 방식). 서버 계정 전.
function nickKey(n){const s=String(n??'').replace(/[\u0000-\u001f<>]/g,'').trim().slice(0,10);return s||'낚시꾼';}
function nickBad(v){const s=String(v||'').trim();if(!s)return '';const low=s.toLowerCase();if(low.includes('관리자')||low.includes('운영자')||low.includes('gm'))return 'reserved';if(window.NK_PROF&&NK_PROF.has&&NK_PROF.has(s))return 'prof';return '';}
function nickBadText(k){return k==='reserved'?'관리자·운영자·GM은 닉네임에 넣을 수 없어요':k==='prof'?'비속어가 포함된 닉네임은 쓸 수 없어요':k==='dup'?'이 호숫가에 같은 닉네임이 있어요':'이 닉네임은 쓸 수 없어요';}
function afAll(){try{const o=JSON.parse(localStorage.getItem('nk_autofish')||'{}');return o&&typeof o==='object'?o:{};}catch(e){return {};}}
function afSave(o){try{localStorage.setItem('nk_autofish',JSON.stringify(o));}catch(e){}}
function myAfKeys(){const keys=new Set();const RT=window.NK_RT;const server=RT&&RT.serverNick?nickKey(RT.serverNick):'';if(server){keys.add(server);return keys;}const add=n=>{const k=nickKey(n);if(k)keys.add(k);};add(NICK());if(S.nick)add(S.nick);if(!String(S.nick||'').trim()){keys.add('나');keys.add('낚시꾼');}return keys;}
function afNow(){const RT=window.NK_RT;const skew=RT&&Number.isFinite(+RT.clockSkew)?+RT.clockSkew:0;return Date.now()-skew;}
function afUntil(who){const A=afAll();if(who!=null&&nickKey(who)!==nickKey(NICK()))return +A[nickKey(who)]||0;let t=0;for(const k of myAfKeys())t=Math.max(t,+A[k]||0);return t>0?t:0;}
function afLeftMs(who){return Math.max(0,afUntil(who)-afNow());}
function afOK(who){return afLeftMs(who)>0;}
function afFmt(ms){const m=Math.max(0,Math.ceil((+ms||0)/60000));if(m<60)return m+'분';const h=Math.floor(m/60),r=m%60;if(h<48)return h+'시간'+(r?' '+r+'분':'');return Math.floor(h/24)+'일';}
function afGrant(who,mins,peerId){const typed=String(who??'').trim();mins=Math.max(1,Math.round(Number(mins)));if(!typed||!(mins>0))return false;who=nickKey(typed);const A=afAll();A[who]=afNow()+mins*60000;afSave(A);const self=myAfKeys().has(who);let sent=false;try{if(V14&&V14.pushGrant)sent=!!V14.pushGrant(who,A[who],false,mins,peerId||'');}catch(e){}if(!self&&!sent){delete A[who];afSave(A);return false;}if(self){try{updAutoBtn();}catch(e){}}return A[who];}
function afRevoke(who,peerId){who=nickKey(who);const A=afAll();if(!A[who])return false;delete A[who];afSave(A);if(myAfKeys().has(who)){if(S.autoFish){S.autoFish=false;try{save();}catch(e){}}try{updAutoBtn();}catch(e){}try{toast('🤖 자동 낚시 이용 시간을 거뒀어요',1800);}catch(e){}}try{if(V14&&V14.pushGrant)V14.pushGrant(who,0,true,0,peerId||'');}catch(e){}return true;}
let _afNote=0;
function afExpire(){if(afOK()){_afNote=0;return false;}if(!S.autoFish)return false;S.autoFish=false;try{save();}catch(e){}if(_afNote!==1){_afNote=1;try{toast('🤖 자동 낚시 이용 시간이 끝났어요<br><small>자동 낚시를 껐어요</small>',2600);}catch(e){}}return true;}
if(S.autoFish&&!afOK())S.autoFish=false;
function lvBaitOK(k){return myLv()>=(LV.baits[k]||1)||lvK().baits.includes(k);}
function lvCharReq(i){if(typeof KINDS==='undefined')return 1;const K=KINDS[i];return (K&&K.lv)||1;}
function lvCharOK(i){return myLv()>=lvCharReq(i)||lvK().chars.includes(i);}

