 q('[data-tmul]').forEach(b=>b.onclick=()=>{S.toastMul=+b.dataset.tmul;S.toastFix=0;up();});q('[data-tfix]').forEach(b=>b.onclick=()=>{S.toastFix=+b.dataset.tfix;up();});g('tToast').onclick=()=>toast('🔔 알림 유지 시간 미리보기',1800);
