 async function login(id,pw){const r=RT();if(!r||!r.status||r.status()!=='on'||!r.auth)return 'offline';const res=await r.auth(String(id==null?'':id).trim(),String(pw==null?'':pw));apply();return res.ok?'ok':(res.reason==='timeout'?'timeout':res.reason==='offline'?'offline':'bad');}
