function tankSlot(key){if(key==null)return null;if(TANKX[key]){const t=TANKX[key];return {S:t.S,G:t.G,j:t.j,t};}if(String(key).startsWith('T')){const t=TWT[+String(key).slice(1)];return t?{S:t.S,G:t.G,j:t.j,t}:null;}const t=DTM[key];return t&&DTANK.stand?{S:DTANK.stand,G:DTANK.glass,j:+key,t}:null;}
