function cslotInit(){if(S.cslot)return;S.cslot={};comboKs().forEach(k=>{const c=S.tank.filter(f=>f.k===k).sort((a,b)=>b.g-a.g||b.cm-a.cm)[0];if(c){S.cslot[k]=c;S.tank=S.tank.filter(x=>x!==c);c.sale=false;}});}
