  m.querySelector('.syasum').innerHTML=P.total?`합계 <b>${P.total}번</b> · 🪙 <b>${P.cost.toLocaleString()}</b>`:'<span class="muted">고른 등급으로 합성할 수 있는 게 없어요</span>';
  const y=$('cfYes');if(y){y.disabled=!P.total;y.textContent=P.total?`⚡ 모두 합성 (${P.total}번)`:'⚡ 모두 합성';}
