 q('[data-sxf]').forEach(b=>b.onclick=()=>{S.fpsCap=+b.dataset.sxf||0;save();re();});q('[data-sxbg]').forEach(b=>b.onclick=()=>{S.bgFps=+b.dataset.sxbg||0;save();re();});q('[data-sxlod]').forEach(b=>b.onclick=()=>{S.lodN=+b.dataset.sxlod||0;save();re();});
