 w.className='v'+(v==='B'||v==='C'?v:'A');w.innerHTML=h;requestAnimationFrame(()=>w.classList.add('on'));
 try{snd&&snd.on&&sfx&&sfx.ding&&sfx.ding();}catch(e){}
