 if($('cfgApply'))$('cfgApply').onclick=()=>{const lay=($('set').querySelector('[name=dLay]:checked')||{}).value||CFG.lay,bots=Math.max(0,Math.min(50,Math.round(+$('botN').value||0)));const deckW=($('set').querySelector('[name=dW]:checked')||{}).value||'';localStorage.setItem('nk_cfg',JSON.stringify(Object.assign({},CFG,{lay,bots,deckW})));S.savedAt=Date.now();save();location.reload();};
 $('saveNow').onclick=()=>{S.savedAt=Date.now();save();toast('💾 저장 완료');renderSet();};
 $('exp').onclick=()=>{S.savedAt=Date.now();save();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(S,null,1)],{type:'application/json'}));a.download=`nakmeong-save-${new Date().toISOString().slice(0,10)}.json`;a.click();};
 function applyImported(o){if(!o||typeof o.coins!=='number')throw 0;Object.keys(S).forEach(k=>delete S[k]);Object.assign(S,S0,o);SYS.migrate(D,S);if(S.autoFish&&!afOK())S.autoFish=false;save();hud();}
 $('imp').onchange=e=>{const f=e.target.files[0];if(!f)return;f.text().then(t=>{try{applyImported(JSON.parse(t));toast('📂 불러오기 완료');renderSet();}catch(_){toast('잘못된 세이브 파일');}});};
 if($('expCode'))$('expCode').onclick=()=>{S.savedAt=Date.now();save();const t=JSON.stringify(S);const done=()=>toast('💾 저장 코드를 복사했어요<br><small>다른 브라우저 설정 › 저장에 붙여넣으세요</small>',2400);if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(t).then(done,()=>{const ta=$('impCode');if(ta){ta.value=t;ta.focus();ta.select();}toast('코드를 아래 칸에 넣어 뒀어요. 길게 눌러 복사해 주세요',2400);});else{const ta=$('impCode');if(ta){ta.value=t;ta.focus();ta.select();}done();}};
 if($('impCodeGo'))$('impCodeGo').onclick=()=>{try{applyImported(JSON.parse($('impCode').value));toast('📂 코드로 불러왔어요');renderSet();}catch(_){toast('코드를 읽지 못했어요. 저장 코드 전체를 붙여넣어 주세요');}};
 if($('setVol'))$('setVol').oninput=e=>{S.vol=+e.target.value;save();};if($('setMute'))$('setMute').onclick=()=>{snd.on=!snd.on;$('setMute').textContent=snd.on?'소리 끄기':'소리 켜기';};if($('setSound'))$('setSound').onclick=()=>{closeM('set');renderSound();openM('sound');};
 $('auOn').onchange=e=>{A.on=e.target.checked;rr();};$('auTh').oninput=e=>{A.th=Math.max(1,+e.target.value||1);save();const z=$('auPrev');if(z)z.textContent=autoPrevTxt();};$('auTh').onchange=e=>{A.th=Math.max(1,+e.target.value||1);rr();};
 const ab=$('auBulk');if(ab)ab.onclick=()=>{const L=autoTargets();if(!L.length)return toast('기준 미만 물고기가 없어요');const sum=L.reduce((a,f)=>a+sellP(f),0);confirmBox(`<h3>어항 일괄 자동판매</h3><p>가치 <b>${A.th}</b>골드 미만 <b>${L.length}마리</b>를 상점가로 팔까요?<br>획득 🪙 <b>${sum.toLocaleString()}</b></p><p class="small muted">🔒 잠금 물고기는 제외</p>`,()=>{const ids=new Set(L.map(f=>f.id));L.forEach(f=>ILOG.add('bulk','fish',f,sellP(f)));S.tank=S.tank.filter(f=>!ids.has(f.id));S.coins+=sum;S.earned+=sum;sfx.coin();toast(`⚙ ${L.length}마리 일괄 판매 +${sum.toLocaleString()}`);rr();});};$('auNew').onchange=e=>{A.keepNew=e.target.checked;rr();};
