  q('[name=ambOne]').forEach(r=>r.onchange=()=>{S.ambOne=r.value;save();});if($('bgmOn'))$('bgmOn').onchange=e=>{S.bgmOff=!e.target.checked;save();};if($('bgmVol'))$('bgmVol').oninput=e=>{S.bgmVol=+e.target.value;save();};$('rainOn').onchange=e=>{S.rainOn=e.target.checked;save();};q('[name=rainR],[name=rainT]').forEach(r=>r.onchange=()=>{S[r.name]=r.value;save();snd.rainForce=r.value;snd.rainV=0;snd.rainK='';clearTimeout(snd._rf);snd._rf=setTimeout(()=>snd.rainForce='',10000);});q('[data-sel]').forEach(b=>b.onclick=()=>{const[c,i]=b.dataset.sel.split(':');if(c==='day')S.sDay=+i;else S.sNight=+i;save();setAmb();renderSound();});
