  dog:g=>{box(g,.36,.24,.5,'#e0a35c',0,.3,0);box(g,.3,.28,.3,'#e0a35c',0,.5,.3);box(g,.16,.12,.14,'#fff1dc',0,.44,.48);box(g,.06,.05,.04,'#2b2230',0,.48,.56);eye(g,-.07,.56,.455);eye(g,.07,.56,.455);[[-.11,.69,.28],[.11,.69,.28]].forEach(([x,y,z])=>box(g,.08,.12,.06,'#b97a3a',x,y,z,[0,0,x<0?.25:-.25]));[[-.12,.1,.17],[.12,.1,.17],[-.12,.1,-.17],[.12,.1,-.17]].forEach(([x,y,z])=>box(g,.08,.2,.08,'#e0a35c',x,y,z));box(g,.06,.06,.2,'#e0a35c',0,.42,-.3,[.7,0,0]);box(g,.2,.1,.02,'#e8584a',0,.4,.17);},
  cat:g=>{box(g,.3,.22,.46,'#9aa0aa',0,.28,0);box(g,.28,.26,.26,'#9aa0aa',0,.48,.26);box(g,.14,.08,.04,'#f2f2f2',0,.42,.39);eye(g,-.07,.52,.395);eye(g,.07,.52,.395);[[-.09,.66,.24],[.09,.66,.24]].forEach(([x,y,z])=>box(g,.08,.1,.05,'#9aa0aa',x,y,z,[0,0,x<0?.2:-.2]));[[-.1,.09,.15],[.1,.09,.15],[-.1,.09,-.15],[.1,.09,-.15]].forEach(([x,y,z])=>box(g,.07,.18,.07,'#9aa0aa',x,y,z));box(g,.05,.05,.36,'#7a808a',0,.5,-.34,[-.9,0,0]);[-.1,0,.1].forEach(x=>box(g,.06,.02,.12,'#6a707a',x,.39,0));},
  duck:g=>{box(g,.36,.3,.46,'#ffd84a',0,.25,0);box(g,.26,.26,.24,'#ffd84a',0,.5,.16);box(g,.16,.06,.12,'#ff8a2a',0,.46,.32);eye(g,-.08,.54,.28);eye(g,.08,.54,.28);box(g,.1,.06,.16,'#ffd84a',-.2,.28,0,[0,0,.3]);box(g,.1,.06,.16,'#ffd84a',.2,.28,0,[0,0,-.3]);box(g,.18,.06,.1,'#ffb02a',0,.42,-.22,[.4,0,0]);},
  rabbit:g=>{box(g,.3,.26,.36,'#f4ece4',0,.25,0);box(g,.26,.26,.24,'#f4ece4',0,.48,.18);eye(g,-.07,.52,.305);eye(g,.07,.52,.305);box(g,.05,.04,.03,'#f29ab0',0,.46,.31);[[-.07,.74,.14],[.07,.74,.14]].forEach(([x,y,z])=>box(g,.07,.28,.04,'#f4ece4',x,y,z,[-.15,0,0]));box(g,.1,.1,.1,'#ffffff',0,.3,-.2);},
  penguin:g=>{box(g,.32,.46,.3,'#2f3542',0,.3,0);box(g,.24,.36,.04,'#ffffff',0,.28,.15);box(g,.12,.05,.1,'#ffb02a',0,.42,.2);eye(g,-.07,.48,.16);eye(g,.07,.48,.16);box(g,.06,.22,.12,'#2f3542',-.19,.3,0,[0,0,.25]);box(g,.06,.22,.12,'#2f3542',.19,.3,0,[0,0,-.25]);box(g,.1,.04,.14,'#ffb02a',-.08,.04,.06);box(g,.1,.04,.14,'#ffb02a',.08,.04,.06);},
  fox:g=>{box(g,.32,.22,.46,'#f08a3c',0,.28,0);box(g,.28,.24,.24,'#f08a3c',0,.47,.27);box(g,.12,.1,.14,'#fff1e4',0,.42,.42);box(g,.05,.04,.03,'#2b2230',0,.45,.5);eye(g,-.07,.52,.395);eye(g,.07,.52,.395);[[-.09,.66,.25],[.09,.66,.25]].forEach(([x,y,z])=>box(g,.09,.14,.05,'#f08a3c',x,y,z,[0,0,x<0?.2:-.2]));[[-.1,.09,.15],[.1,.09,.15],[-.1,.09,-.15],[.1,.09,-.15]].forEach(([x,y,z])=>box(g,.07,.18,.07,'#3a2a24',x,y,z));box(g,.16,.16,.36,'#f08a3c',0,.36,-.36,[.5,0,0]);box(g,.12,.12,.1,'#fff1e4',0,.48,-.52,[.5,0,0]);},
