function veUndoBtns(){const m=$('vmEd');if(!m)return;const u=m.querySelector('[data-veundo]'),r=m.querySelector('[data-veredo]');if(u)u.disabled=!VE.undo.length;if(r)r.disabled=!VE.redo.length;}
